import React, { useState, createContext, useContext } from "react";

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState({});

  const login = (user) => {
    setUser(user);
    setIsAuthenticated(true);
  };

  const logout = () => {
    setUser({});
    setIsAuthenticated(false);
  };

  const value = {
    isAuthenticated,
    user,
    login,
    logout,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from "react";
import { ethers } from "ethers";
import { useSnackbar } from "notistack";
import {
  BOT_CHAIN_CHAIN_ID,
  BOT_CHAIN_RPC,
  BOT_CHAIN_NAME,
  BOT_CHAIN_NATIVE_CURRENCY,
  BOT_CHAIN_HEX_CHAIN_ID,
  BOT_CHAIN_EXPLORER,
} from "../constants";

const WalletContext = createContext();

export const useWallet = () => useContext(WalletContext);

const networkParams = {
  chainId: BOT_CHAIN_HEX_CHAIN_ID,
  chainName: BOT_CHAIN_NAME,
  nativeCurrency: { name: BOT_CHAIN_NATIVE_CURRENCY, symbol: BOT_CHAIN_NATIVE_CURRENCY, decimals: 18 },
  rpcUrls: [BOT_CHAIN_RPC],
  blockExplorerUrls: [BOT_CHAIN_EXPLORER],
};

export const WalletProvider = ({ children }) => {
  const { enqueueSnackbar } = useSnackbar();
  const [account, setAccount] = useState(null);
  const [chainId, setChainId] = useState(null);
  const [balance, setBalance] = useState("0");
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [isConnecting, setIsConnecting] = useState(false);

  const refreshBalance = useCallback(async (addr, prov) => {
    if (!addr || !prov) return;
    try {
      const bal = await prov.getBalance(addr);
      setBalance(ethers.utils.formatEther(bal));
    } catch {
      setBalance("0");
    }
  }, []);

  const handleAccountsChanged = useCallback(
    async (accounts) => {
      if (!accounts || accounts.length === 0) {
        setAccount(null);
        setSigner(null);
        return;
      }
      const addr = accounts[0];
      setAccount(addr);
      const prov = new ethers.providers.Web3Provider(window.ethereum, "any");
      setProvider(prov);
      setSigner(prov.getSigner());
      await refreshBalance(addr, prov);
    },
    [refreshBalance]
  );

  const handleChainChanged = useCallback(
    async (cid) => {
      const id = Number(cid);
      setChainId(id);
      if (window.ethereum) {
        const prov = new ethers.providers.Web3Provider(window.ethereum, "any");
        setProvider(prov);
        if (account) {
          setSigner(prov.getSigner());
          await refreshBalance(account, prov);
        }
      }
    },
    [account, refreshBalance]
  );

  useEffect(() => {
    if (window.ethereum) {
      window.ethereum.on("accountsChanged", handleAccountsChanged);
      window.ethereum.on("chainChanged", handleChainChanged);
      window.ethereum.request({ method: "eth_chainId" }).then(handleChainChanged);
      window.ethereum.request({ method: "eth_accounts" }).then(handleAccountsChanged);
    }
    return () => {
      if (window.ethereum) {
        window.ethereum.removeListener("accountsChanged", handleAccountsChanged);
        window.ethereum.removeListener("chainChanged", handleChainChanged);
      }
    };
  }, [handleAccountsChanged, handleChainChanged]);

  useEffect(() => {
    if (!account || !provider) return;
    const id = setInterval(() => refreshBalance(account, provider), 15000);
    return () => clearInterval(id);
  }, [account, provider, refreshBalance]);

  const isCorrectNetwork = chainId === BOT_CHAIN_CHAIN_ID;

  const connect = async () => {
    if (!window.ethereum) {
      enqueueSnackbar("MetaMask not detected. Please install MetaMask.", { variant: "error" });
      return;
    }
    try {
      setIsConnecting(true);
      const prov = new ethers.providers.Web3Provider(window.ethereum, "any");
      await prov.send("eth_requestAccounts", []);
      const network = await prov.getNetwork();
      setChainId(network.chainId);
      const signer = prov.getSigner();
      const addr = await signer.getAddress();
      setAccount(addr);
      setProvider(prov);
      setSigner(signer);
      await refreshBalance(addr, prov);
      if (network.chainId !== BOT_CHAIN_CHAIN_ID) {
        enqueueSnackbar("Please switch to the BOT Chain network.", { variant: "warning" });
      }
    } catch (err) {
      console.error(err);
      enqueueSnackbar(err?.message || "Failed to connect wallet", { variant: "error" });
    } finally {
      setIsConnecting(false);
    }
  };

  const switchNetwork = async () => {
    if (!window.ethereum) return;
    try {
      await window.ethereum.request({
        method: "wallet_switchEthereumChain",
        params: [{ chainId: BOT_CHAIN_HEX_CHAIN_ID }],
      });
    } catch (switchError) {
      if (switchError.code === 4902) {
        try {
          await window.ethereum.request({
            method: "wallet_addEthereumChain",
            params: [networkParams],
          });
        } catch (addError) {
          enqueueSnackbar("Could not add BOT Chain network", { variant: "error" });
        }
      } else {
        console.error(switchError);
      }
    }
  };

  const disconnect = () => {
    setAccount(null);
    setSigner(null);
    setBalance("0");
    setChainId(null);
  };

  const value = {
    account,
    chainId,
    balance,
    provider,
    signer,
    isConnecting,
    isConnected: !!account,
    isCorrectNetwork,
    connect,
    disconnect,
    switchNetwork,
    refreshBalance: () => refreshBalance(account, provider),
  };

  return <WalletContext.Provider value={value}>{children}</WalletContext.Provider>;
};

