                      href={explorerLink(item.hash)}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-purple-700 underline text-sm"
                    >
                      View
                    </a>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      ) : (
        <p className="text-center mt-20 text-gray-500 text-lg">No transactions yet</p>
      )}
    </div>
  );
};

